from solution import count_char_position


def test_issue_example_xbcefg():
    """Example from issue: 'xbcefg' counts 2 matches."""
    assert count_char_position("xbcefg") == 2  # 0+1+1+0+0+0 = 2


def test_issue_empty_string():
    """Empty string has no positions so count is 0."""
    assert count_char_position("") == 0  # 0+0 = 0


def test_issue_single_a_lowercase():
    """Single 'a' matches the first alphabet letter."""
    assert count_char_position("a") == 1  # 0+1 = 1


def test_issue_single_A_uppercase():
    """Uppercase 'A' matches case-insensitively."""
    assert count_char_position("A") == 1  # 0+1 = 1


def test_issue_single_b_wrong_position():
    """Single 'b' at first position does not match 'a'."""
    assert count_char_position("b") == 0  # 0+0 = 0


def test_issue_full_lowercase_alphabet():
    """Full lowercase alphabet matches at every position."""
    assert count_char_position("abcdefghijklmnopqrstuvwxyz") == 26  # 26*1 = 26


def test_issue_full_uppercase_alphabet():
    """Full uppercase alphabet matches case-insensitively."""
    assert count_char_position("ABCDEFGHIJKLMNOPQRSTUVWXYZ") == 26  # 26*1 = 26


def test_issue_mixed_case_full_alphabet():
    """Mixed-case full alphabet still matches everywhere."""
    assert count_char_position("AbCdEfGhIjKlMnOpQrStUvWxYz") == 26  # 26*1 = 26


def test_issue_position_not_containment():
    """'ba' contains a and b but at wrong positions so count is 0."""
    assert count_char_position("ba") == 0  # 0+0 = 0


def test_issue_no_match_xyz():
    """Characters out of position are not counted."""
    assert count_char_position("xyz") == 0  # 0+0+0 = 0


def test_contract_longer_than_alphabet():
    """Extra characters beyond 'z' cannot match alphabet positions."""
    assert count_char_position("abcdefghijklmnopqrstuvwxyzABC") == 26  # 26+0+0+0 = 26


def test_contract_nonletter_does_not_match():
    """Non-alphabet characters cannot equal the alphabet letter."""
    assert count_char_position("a1c") == 2  # 1+0+1 = 2
